import{az as t,P as e,Q as s,aQ as l}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const y=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"面试题/服务端/index.md","filePath":"面试题/服务端/index.md","lastUpdated":1785339991000}'),n={name:"面试题/服务端/index.md"};function d(r,a,o,i,c,p){return e(),s("div",null,[...a[0]||(a[0]=[l(`<h2 id="服务端面试题汇总" tabindex="-1">服务端面试题汇总 <a class="header-anchor" href="#服务端面试题汇总" aria-label="Permalink to “服务端面试题汇总”">​</a></h2><p><a href="https://nodejs.org/zh-cn/docs/" target="_blank" rel="noreferrer">Node.js 面试题集合</a></p><p>本页面汇总服务端开发高频面试题，涵盖网络协议、Node.js、数据库、安全防护等核心领域。每道题附有要点解析，帮助系统复习后端知识体系。</p><h2 id="网络协议" tabindex="-1">网络协议 <a class="header-anchor" href="#网络协议" aria-label="Permalink to “网络协议”">​</a></h2><h3 id="q1-http-和-https-的区别是什么" tabindex="-1">Q1: HTTP 和 HTTPS 的区别是什么？ <a class="header-anchor" href="#q1-http-和-https-的区别是什么" aria-label="Permalink to “Q1: HTTP 和 HTTPS 的区别是什么？”">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>HTTP</th><th>HTTPS</th></tr></thead><tbody><tr><td>端口</td><td>80</td><td>443</td></tr><tr><td>安全性</td><td>明文传输</td><td>TLS/SSL 加密</td></tr><tr><td>证书</td><td>不需要</td><td>需要 CA 证书</td></tr><tr><td>性能</td><td>较快</td><td>略慢（握手开销）</td></tr></tbody></table><p>HTTPS 在 HTTP 基础上加入 TLS 层，通过非对称加密协商密钥，对称加密传输数据，保证机密性与完整性。</p><h3 id="q2-tcp-三次握手为什么不是两次" tabindex="-1">Q2: TCP 三次握手为什么不是两次？ <a class="header-anchor" href="#q2-tcp-三次握手为什么不是两次" aria-label="Permalink to “Q2: TCP 三次握手为什么不是两次？”">​</a></h3><p>两次握手无法防止历史失效连接。若客户端的 SYN 延迟到达，服务器回复后误以为连接已建立，会浪费资源。第三次握手让客户端确认连接有效性，同时防止 SYN 泛洪攻击。</p><h3 id="q3-cors-预检请求何时触发" tabindex="-1">Q3: CORS 预检请求何时触发？ <a class="header-anchor" href="#q3-cors-预检请求何时触发" aria-label="Permalink to “Q3: CORS 预检请求何时触发？”">​</a></h3><p>当请求不满足&quot;简单请求&quot;条件时触发预检（OPTIONS）。常见触发场景：使用了 PUT/DELETE 方法、Content-Type 为 application/json、设置了自定义请求头。预检通过后浏览器才发送实际请求。</p><h2 id="node-js" tabindex="-1">Node.js <a class="header-anchor" href="#node-js" aria-label="Permalink to “Node.js”">​</a></h2><h3 id="q4-node-js-事件循环的阶段有哪些" tabindex="-1">Q4: Node.js 事件循环的阶段有哪些？ <a class="header-anchor" href="#q4-node-js-事件循环的阶段有哪些" aria-label="Permalink to “Q4: Node.js 事件循环的阶段有哪些？”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 事件循环六个阶段</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 1. timers：执行 setTimeout/setInterval 回调</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 2. pending callbacks：系统级回调</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 3. idle/prepare：内部使用</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 4. poll：I/O 事件回调</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 5. check：setImmediate 回调</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 6. close callbacks：关闭事件回调</span></span></code></pre></div><p>每个阶段结束后，会清空微任务队列（process.nextTick 优先于 Promise）。</p><h3 id="q5-process-nexttick-和-promise-then-的区别" tabindex="-1">Q5: process.nextTick 和 Promise.then 的区别？ <a class="header-anchor" href="#q5-process-nexttick-和-promise-then-的区别" aria-label="Permalink to “Q5: process.nextTick 和 Promise.then 的区别？”">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>process.nextTick</th><th>Promise.then</th></tr></thead><tbody><tr><td>优先级</td><td>最高</td><td>次高</td></tr><tr><td>执行时机</td><td>每个阶段后、微任务前</td><td>微任务阶段</td></tr><tr><td>用途</td><td>紧跟当前操作</td><td>异步流程控制</td></tr></tbody></table><h3 id="q6-commonjs-和-es-modules-的区别" tabindex="-1">Q6: CommonJS 和 ES Modules 的区别？ <a class="header-anchor" href="#q6-commonjs-和-es-modules-的区别" aria-label="Permalink to “Q6: CommonJS 和 ES Modules 的区别？”">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>CommonJS</th><th>ES Modules</th></tr></thead><tbody><tr><td>加载方式</td><td>运行时（同步）</td><td>编译时（静态）</td></tr><tr><td>this</td><td>module.exports</td><td>undefined</td></tr><tr><td>循环引用</td><td>返回已执行部分</td><td>引用绑定</td></tr><tr><td>Tree-shaking</td><td>不支持</td><td>支持</td></tr></tbody></table><h2 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to “数据库”">​</a></h2><h3 id="q7-mysql-索引为什么用-b-树" tabindex="-1">Q7: MySQL 索引为什么用 B+ 树？ <a class="header-anchor" href="#q7-mysql-索引为什么用-b-树" aria-label="Permalink to “Q7: MySQL 索引为什么用 B+ 树？”">​</a></h3><p>B+ 树的非叶子节点不存数据，每个节点能容纳更多索引，树更矮，磁盘 I/O 更少。叶子节点通过链表相连，范围查询高效。相比 B 树，B+ 树更适合磁盘存储的数据结构。</p><h3 id="q8-事务的隔离级别有哪些" tabindex="-1">Q8: 事务的隔离级别有哪些？ <a class="header-anchor" href="#q8-事务的隔离级别有哪些" aria-label="Permalink to “Q8: 事务的隔离级别有哪些？”">​</a></h3><table tabindex="0"><thead><tr><th>隔离级别</th><th>脏读</th><th>不可重复读</th><th>幻读</th></tr></thead><tbody><tr><td>READ UNCOMMITTED</td><td>可能</td><td>可能</td><td>可能</td></tr><tr><td>READ COMMITTED</td><td>不可能</td><td>可能</td><td>可能</td></tr><tr><td>REPEATABLE READ</td><td>不可能</td><td>不可能</td><td>可能</td></tr><tr><td>SERIALIZABLE</td><td>不可能</td><td>不可能</td><td>不可能</td></tr></tbody></table><p>MySQL 默认 REPEATABLE READ，通过 MVCC + 间隙锁解决幻读。</p><h3 id="q9-redis-为什么快" tabindex="-1">Q9: Redis 为什么快？ <a class="header-anchor" href="#q9-redis-为什么快" aria-label="Permalink to “Q9: Redis 为什么快？”">​</a></h3><ol><li>纯内存操作，无磁盘 I/O</li><li>单线程，无锁竞争与上下文切换</li><li>I/O 多路复用（epoll）</li><li>高效的数据结构（SDS、跳表、压缩列表）</li></ol><h2 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to “安全”">​</a></h2><h3 id="q10-xss-和-csrf-的区别" tabindex="-1">Q10: XSS 和 CSRF 的区别？ <a class="header-anchor" href="#q10-xss-和-csrf-的区别" aria-label="Permalink to “Q10: XSS 和 CSRF 的区别？”">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>XSS</th><th>CSRF</th></tr></thead><tbody><tr><td>攻击目标</td><td>用户浏览器</td><td>服务器</td></tr><tr><td>核心手段</td><td>注入恶意脚本</td><td>冒用用户身份</td></tr><tr><td>防御方式</td><td>转义、CSP</td><td>Token、SameSite</td></tr></tbody></table><h3 id="q11-如何防御-sql-注入" tabindex="-1">Q11: 如何防御 SQL 注入？ <a class="header-anchor" href="#q11-如何防御-sql-注入" aria-label="Permalink to “Q11: 如何防御 SQL 注入？”">​</a></h3><p>核心是参数化查询，将数据与 SQL 结构分离。使用预编译语句或 ORM 框架，辅以输入校验和最小权限原则。永远不要直接拼接用户输入构造 SQL。</p><h2 id="实战场景" tabindex="-1">实战场景 <a class="header-anchor" href="#实战场景" aria-label="Permalink to “实战场景”">​</a></h2><h3 id="q12-如何设计一个短链系统" tabindex="-1">Q12: 如何设计一个短链系统？ <a class="header-anchor" href="#q12-如何设计一个短链系统" aria-label="Permalink to “Q12: 如何设计一个短链系统？”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 1. 生成：长 URL -&gt; 哈希（如 Base62 编码）-&gt; 短码</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 2. 存储：短码 &lt;-&gt; 长 URL 映射存入数据库/Redis</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 3. 访问：短码 -&gt; 查库 -&gt; 301/302 重定向到长 URL</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 4. 优化：Redis 缓存热点短链，布隆过滤器防穿透</span></span></code></pre></div><h3 id="q13-如何实现接口限流" tabindex="-1">Q13: 如何实现接口限流？ <a class="header-anchor" href="#q13-如何实现接口限流" aria-label="Permalink to “Q13: 如何实现接口限流？”">​</a></h3><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;">// 滑动窗口限流（Redis + Lua）</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">// 每个用户每分钟最多 100 次请求</span></span>
<span class="line"><span style="color:#C792EA;">const</span><span style="color:#BABED8;"> lua </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;"> \`</span></span>
<span class="line"><span style="color:#C3E88D;">  local key = KEYS[1]</span></span>
<span class="line"><span style="color:#C3E88D;">  local limit = tonumber(ARGV[1])</span></span>
<span class="line"><span style="color:#C3E88D;">  local window = tonumber(ARGV[2])</span></span>
<span class="line"><span style="color:#C3E88D;">  local current = redis.call(&#39;ZCARD&#39;, key)</span></span>
<span class="line"><span style="color:#C3E88D;">  if current &gt;= limit then return 0 end</span></span>
<span class="line"><span style="color:#C3E88D;">  redis.call(&#39;ZADD&#39;, key, ARGV[3], ARGV[3])</span></span>
<span class="line"><span style="color:#C3E88D;">  redis.call(&#39;EXPIRE&#39;, key, window)</span></span>
<span class="line"><span style="color:#C3E88D;">  return 1</span></span>
<span class="line"><span style="color:#89DDFF;">\`</span><span style="color:#89DDFF;">;</span></span></code></pre></div><h3 id="q14-websocket-如何实现广播" tabindex="-1">Q14: WebSocket 如何实现广播？ <a class="header-anchor" href="#q14-websocket-如何实现广播" aria-label="Permalink to “Q14: WebSocket 如何实现广播？”">​</a></h3><p>维护一个连接池，收到消息时遍历所有连接发送。大规模场景下可使用 Redis Pub/Sub 跨进程广播。详见 <a href="./通讯/websocket/广播">WebSocket 广播实现</a>。</p><h2 id="系统设计" tabindex="-1">系统设计 <a class="header-anchor" href="#系统设计" aria-label="Permalink to “系统设计”">​</a></h2><h3 id="q15-如何设计一个秒杀系统" tabindex="-1">Q15: 如何设计一个秒杀系统？ <a class="header-anchor" href="#q15-如何设计一个秒杀系统" aria-label="Permalink to “Q15: 如何设计一个秒杀系统？”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 1. 前端：按钮防抖、验证码、静态页面 CDN</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 2. 网关：限流（令牌桶）、IP 黑名单</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 3. 缓存：库存预热到 Redis，原子扣减（DECR/Lua）</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 4. 消息队列：异步下单，削峰填谷</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 5. 数据库：最终一致性扣减库存</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 6. 兜底：超卖补偿、库存回滚</span></span></code></pre></div><p>服务端面试考察范围广，从网络协议到底层原理，从数据库设计到系统架构。复习时注重理解原理而非死记硬背，结合实际项目经验组织答案，展示深度与广度。</p>`,43)])])}const m=t(n,[["render",d]]);export{y as __pageData,m as default};
